import { useState, useEffect } from 'react';
export const useChromeVisibility = ({
  chrome
}) => {
  const [isVisible, setIsVisible] = useState(true);
  useEffect(() => {
    const subscription = chrome.getIsVisible$().subscribe(value => {
      setIsVisible(value);
    });
    return () => subscription.unsubscribe();
  }, [chrome]);
  return isVisible;
};